-- crash-edit/update-crash
-- Saves the crash facts only if nobody changed it since the editor loaded it (the `version` must match). Raises the version.
--
-- Parameters, with the example values used to render this file:
--   $1 = "Bus fell off the road"
--   $2 = null
--   $3 = "2026-11-12"
--   $4 = "05:45"
--   $5 = "Example bazaar"
--   $6 = null
--   $7 = "0199c8a0-0000-7000-8000-00000000000a"
--   $8 = "0199c8a0-0000-7000-8000-00000000000a"
--   $9 = 3
--   $10 = 5
--   $11 = "0199c8a0-0000-7000-8000-00000000000a"
--   $12 = 2
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

update "crashes"
set "title_en" = $1, "title_np" = $2, "occurred_on" = $3, "occurred_time" = $4, "place_name_en" = $5, "place_name_np" = $6, "province_id" = $7, "district_id" = $8, "deaths" = $9, "injured_total" = $10, "version" = "crashes"."version" + 1, "updated_at" = now()
where ("crashes"."id" = $11
  and "crashes"."version" = $12)
returning "id", "slug", "status", "merged_into_id", "title_en", "title_np", "occurred_on", "occurred_time", "location", "location_precision", "place_name_en", "place_name_np", "province_id", "district_id", "local_unit_id", "deaths", "injured_total", "created_via", "verification_level", "version", "created_at", "updated_at";
